const verdicts = $input.all();
const answers = $('Basic LLM Chain').all();
const tests = $('Code in JavaScript').all();
let kwPassed = 0, judgePassed = 0, agree = 0;

const rows = verdicts.map((v, i) => {
  const t = tests[i].json;
  const answer = answers[i].json.text || "";
  const verdict = (v.json.text || "").trim();
  const hit = t.expected.find(e => answer.toLowerCase().includes(e.toLowerCase()));
  const keyword_pass = Boolean(hit);
  const judge_pass = verdict.toUpperCase().startsWith("PASS");
  const judge_reason = verdict.split("\n").slice(1).join(" ").trim();
  if (keyword_pass) kwPassed++;
  if (judge_pass) judgePassed++;
  if (keyword_pass === judge_pass) agree++;
  return { json: { id: t.id, question: t.question, answer, keyword_pass, judge_pass, judge_reason, agree: keyword_pass === judge_pass } };
});

const n = verdicts.length;
rows.push({ json: { id: "TOTAL", question: `keyword: ${kwPassed}/${n} | judge: ${judgePassed}/${n} | agree: ${agree}/${n}` } });

return rows;
